-- Append-only manual recovery audit trail; operation identity is stored only as a short safe reference.
CREATE TABLE recovery_audit_log (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, article_id BIGINT UNSIGNED NOT NULL, step_name VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL, action VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, actor VARCHAR(128) NOT NULL, previous_state VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, new_state VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, operation_ref VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL, details_json JSON NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), KEY idx_recovery_audit_article_created (article_id, created_at), CONSTRAINT fk_recovery_audit_article FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
